import{_ as a,o as t,c as r,ah as i}from"./chunks/framework.DDXs_i7t.js";const m=JSON.parse('{"title":"Christian Mattura & das Pilnacek-Tape","description":"","frontmatter":{},"headers":[],"relativePath":"recherche/christian-mattura-pilnacek-tape.md","filePath":"recherche/christian-mattura-pilnacek-tape.md"}'),n={name:"recherche/christian-mattura-pilnacek-tape.md"};function s(h,e,u,l,c,o){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="christian-mattura-das-pilnacek-tape" tabindex="-1">Christian Mattura &amp; das Pilnacek-Tape <a class="header-anchor" href="#christian-mattura-das-pilnacek-tape" aria-label="Permalink to &quot;Christian Mattura &amp; das Pilnacek-Tape&quot;">​</a></h1><p><strong>Status:</strong> Aktiv recherchiert (Stand: 12. März 2026)<br><strong>Rolle:</strong> Kronzeuge der akustischen Forensik<br><strong>Bedeutung:</strong> Urheber der heimlichen Aufnahme von Christian Pilnacek</p><hr><h2 id="🎙️-das-„pilnacek-tape-22-minuten-wahrheit" tabindex="-1">🎙️ Das „Pilnacek-Tape“: 22 Minuten Wahrheit <a class="header-anchor" href="#🎙️-das-„pilnacek-tape-22-minuten-wahrheit" aria-label="Permalink to &quot;🎙️ Das „Pilnacek-Tape“: 22 Minuten Wahrheit&quot;">​</a></h2><p>Im November 2023 gelangte eine 22-minütige Tonaufnahme an die Öffentlichkeit, die das politische System Österreichs in seinen Grundfesten erschütterte. Die Aufnahme entstand in einem Wiener Restaurant („Prinz Eugen“) und zeigt einen Christian Pilnacek, der über den massiven Druck der ÖVP auf ihn und die Justiz klagt.</p><h3 id="zentrale-zitate-aus-dem-tape" tabindex="-1"><strong>Zentrale Zitate aus dem Tape:</strong> <a class="header-anchor" href="#zentrale-zitate-aus-dem-tape" aria-label="Permalink to &quot;**Zentrale Zitate aus dem Tape:**&quot;">​</a></h3><blockquote><p><em>„Die ÖVP ist nicht meine Partei. Das sind keine Demokraten.“</em><em>„Wer hat mich denn am meisten gequält? Die ÖVP!“</em><em>„Sobotka ist der schlimmste von allen.“</em></p></blockquote><hr><h2 id="👤-wer-ist-christian-mattura" tabindex="-1">👤 Wer ist Christian Mattura? <a class="header-anchor" href="#👤-wer-ist-christian-mattura" aria-label="Permalink to &quot;👤 Wer ist Christian Mattura?&quot;">​</a></h2><p>Christian Mattura ist ein österreichischer Unternehmer und Lobbyist (ehemals Glücksspielbereich). Er ist die Person, die das Gespräch mit Pilnacek heimlich aufgezeichnet hat.</p><h3 id="motivation-laut-mattura" tabindex="-1"><strong>Motivation laut Mattura:</strong> <a class="header-anchor" href="#motivation-laut-mattura" aria-label="Permalink to &quot;**Motivation laut Mattura:**&quot;">​</a></h3><p>Er gab im U-Ausschuss am 12. März 2026 an, die Aufnahme gemacht zu haben, um das „System endlich zu ändern“. Er habe Pilnacek als gebrochenen Mann erlebt, der unter dem Gewicht politischer Interventionen litt.</p><hr><h2 id="⚖️-das-„match-im-u-ausschuss-12-03-2026" tabindex="-1">⚖️ Das „Match“ im U-Ausschuss (12.03.2026) <a class="header-anchor" href="#⚖️-das-„match-im-u-ausschuss-12-03-2026" aria-label="Permalink to &quot;⚖️ Das „Match“ im U-Ausschuss (12.03.2026)&quot;">​</a></h2><p>Bei seiner Befragung kam es zu einem beispiellosen Schlagabtausch mit der ÖVP:</p><ul><li><strong>Hanger-Skala:</strong> Mattura attackierte Andreas Hanger (ÖVP) direkt für seine Diskreditierungstaktiken.</li><li><strong>Der Laptop:</strong> Mattura brachte neue Aussagen über Versuche ins Spiel, Pilnaceks Laptop „verschwinden“ zu lassen.</li><li><strong>Glaubwürdigkeit:</strong> Die ÖVP versucht, Mattura aufgrund seiner geschäftlichen Vergangenheit als unglaubwürdig darzustellen – ein klassisches Manöver der „Harten Prosa“.</li></ul><hr><h2 id="🎬-relevanz-fur-„das-horten-mysterium" tabindex="-1">🎬 Relevanz für „Das Horten-Mysterium“ <a class="header-anchor" href="#🎬-relevanz-fur-„das-horten-mysterium" aria-label="Permalink to &quot;🎬 Relevanz für „Das Horten-Mysterium“&quot;">​</a></h2><p>In unserer Mockumentary dient Christian Mattura als Vorbild für die Figur des <strong>„Chronisten des Geheimen“</strong>.</p><ul><li><strong>Motiv:</strong> Die Ästhetik des heimlichen Mitschnitts.</li><li><strong>Teil 4:</strong> Wir werden die Szene im Restaurant filmisch rekonstruieren, um die „Kälte der Intervention“ spürbar zu machen.</li></ul><hr><p>👈 <a href="/recherche/postenschacher.html">Zurück zur Recherche-Übersicht</a></p>',22)])])}const p=a(n,[["render",s]]);export{m as __pageData,p as default};
